import assert from "node:assert/strict";
import test from "node:test";
import { changeLabelPolicy, defaultLabelPolicy, sameLabelPolicy } from "../../../main/frontend/graph-explorer/label-policy.ts";

const stored = defaultLabelPolicy(["en"]);
const view = { languages: ["nb"], properties: ["urn:name"], languagesConfigured: true, propertiesConfigured: true };
const start = () => ({ shown: stored, stored, local: 0 });

test("a saved view's label policy is shown, not stored, and an edit stores only what was edited", () => {
  let state = changeLabelPolicy(start(), { kind: "show", policy: view });
  assert.deepEqual(state.shown, view);
  assert.deepEqual(state.stored, stored);
  state = changeLabelPolicy(state, { kind: "edit", edit: { languages: ["de"], languagesConfigured: true } });
  assert.deepEqual(state.stored, { ...stored, languages: ["de"], languagesConfigured: true },
    "the view's label predicates do not become the preference");
  assert.deepEqual(state.shown, { ...view, languages: ["de"] });
  state = changeLabelPolicy(state, { kind: "revert" });
  assert.deepEqual(state.shown, state.stored, "a graph without a view shows the stored preference again");
});

test("only changes made in this page count as local", () => {
  let state = changeLabelPolicy(start(), { kind: "follow", policy: view });
  assert.equal(state.local, 0, "another tab's preference");
  assert.deepEqual(state.shown, view);
  assert.deepEqual(state.stored, view);
  state = changeLabelPolicy(start(), { kind: "locales", languages: ["fr"] });
  assert.equal(state.local, 0, "the browser's languages");
  assert.deepEqual(state.shown.languages, ["fr"]);
  assert.deepEqual(changeLabelPolicy({ ...start(), shown: view }, { kind: "locales", languages: ["fr"] }).shown, view,
    "configured languages do not follow the browser");
  for (const change of [{ kind: "edit", edit: { languages: ["de"] } }, { kind: "show", policy: view }, { kind: "revert" }]) {
    assert.equal(changeLabelPolicy(start(), change).local, 1, change.kind);
  }
});

test("a page follows the preferences until it shows a saved view's own policy", () => {
  let state = changeLabelPolicy(start(), { kind: "edit", edit: { languages: ["nb"], languagesConfigured: true } });
  assert.ok(sameLabelPolicy(state.shown, state.stored), "an edit of the preferences is still following them");
  state = changeLabelPolicy(state, { kind: "show", policy: view });
  assert.ok(!sameLabelPolicy(state.shown, state.stored), "a saved view's own policy");
  state = changeLabelPolicy(state, { kind: "revert" });
  assert.ok(sameLabelPolicy(state.shown, state.stored));
  assert.ok(!sameLabelPolicy(view, { ...view, properties: ["urn:other"] }));
  assert.ok(!sameLabelPolicy(view, { ...view, languages: ["nb", "en"] }));
  assert.ok(!sameLabelPolicy(view, { ...view, propertiesConfigured: false }));
});
